import Image from "next/image";

export default function Hero() {
  return (
    <section
      id="home"
      className="min-h-screen flex items-center justify-center 
                 bg-gradient-to-b from-black via-gray-900 to-black 
                 text-white px-6"
    >
      <div className="max-w-6xl mx-auto grid md:grid-cols-2 gap-10 items-center">
        
        {/* TEXT CONTENT */}
        <div className="text-center md:text-left">
          <h1 className="text-4xl sm:text-5xl md:text-6xl font-extrabold leading-tight">
            Hi, I’m{" "}
            <span className="text-blue-500">Bishmeeta Thapa</span>
          </h1>

          <p className="mt-4 text-base sm:text-lg md:text-xl text-gray-300">
            Frontend Developer | React | Next.js | Tailwind CSS
          </p>

          <p className="mt-6 text-gray-400 max-w-xl">
            I build modern, responsive, and user-friendly web applications
            focused on clean UI and smooth user experience.
          </p>

          <div className="mt-10 flex flex-col sm:flex-row gap-4 md:justify-start justify-center">
            <a
              href="#projects"
              className="px-8 py-3 rounded-lg bg-blue-600 
                         hover:bg-blue-700 transition duration-300 
                         font-medium"
            >
              View Projects
            </a>

            <a
              href="#contact"
              className="px-8 py-3 rounded-lg border border-gray-500 
                         hover:border-white transition duration-300 
                         font-medium"
            >
              Contact Me
            </a>
          </div>
        </div>

        {/* IMAGE */}
        <div className="flex justify-center md:justify-end">
          <div className="relative w-64 h-64 md:w-80 md:h-80 rounded-full 
                          overflow-hidden border-4 border-blue-600 shadow-lg">
            <Image
              src="/profile.png"
              alt="Bishmeeta Thapa"
              fill
              className="object-cover"
              priority
            />
          </div>
        </div>

      </div>
    </section>
  );
}
